content.text:
    head[1] = (uint8_t)(len & 0xffu);
    head[2] = (uint8_t)((len >> 8) & 0xffu);
    head[3] = (uint8_t)((len >> 16) & 0xffu);
    head[4] = (uint8_t)((len >> 24) & 0xffu);
    sha_update(&c->sha, head, 5);
    sha_update(&c->sha, frame, len);
    c->packets++;
    c->bytes += (uint64_t)len;
    if (ack) {
        c->n_tx_ack++;
    } else {
        c->n_tx_data++;
    }
    if (c->trace_count < c->trace_limit) {
        epic_trace_t *t = &c->trace[c->trace_count++];
        t->len = (uint32_t)len;
        t->rank = (uint8_t)rank;
        memcpy(t->frame, frame, len);
    }
    return true;
}

static bool send_ack_to(collector_t *c, int rank, uint32_t prefix) {
    size_t len = epic_build_roce_ack(c->out, sizeof(c->out), c->mac_sw[rank], c->mac_host[rank],
                                     c->ip_sw[rank], c->ip_host[rank], EPIC_ROCE_UDP_PORT,
                                     EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)rank,
                                     (c->start + prefix - 1u) & M24);
    if (!len) {
        return false;
    }
    return emit_frame(c, rank, c->out, len, true);
}

static bool send_output(collector_t *c, int d, uint32_t q) {
    uint32_t p;
    int src;
    if (!output_map(c, d, q, &p, &src)) {
        return false;
    }
    slot_t *s = slot_of(c, p);
    if (!s) {
        return false;
    }
    uint32_t psn = (c->start + q) & M24;
    size_t len;
    if (c->primitive == P_ALLGATHER) {
        if (!s->g[src]) {
            return false;
        }
        len = epic_build_roce_data_raw(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                       c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn, s->g[src],
                                       c->plen);
    } else if (c->primitive == P_BCAST) {
        len = epic_build_roce_data_raw(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                       c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn,
                                       slot_payload(c, p), c->plen);
    } else {
        len = epic_build_roce_data(c->out, sizeof(c->out), c->mac_sw[d], c->mac_host[d],
                                   c->ip_sw[d], c->ip_host[d], EPIC_ROCE_UDP_PORT,
                                   EPIC_ROCE_UDP_PORT, 0x100u + (uint32_t)d, psn,
                                   (const int32_t *)slot_payload(c, p), c->plen);
    }
    if (!len) {
        return false;
    }
    return emit_frame(c, d, c->out, len, false);
}

/* ------------------------- eligibility and safety ------------------------- */

static bool contribution_safe(const collector_t *c, int r, uint32_t p) {
    if (c->mode == MODE_OWN) {
        return true;
    }
    switch (c->primitive) {
    case P_ALLREDUCE:
    case P_BARRIER:
        return c->acked[r] > p;
    case P_REDUCE:
        return c->acked[c->root] > p;
    case P_BCAST:
        for (int d = 0; d < 4; d++) {
            if (d == c->root) {
                continue;
            }
            if (c->acked[d] <= p) {
                return false;
            }
        }
        return true;
    case P_RSCATTER:
        return c->acked[p / c->quarter] > p % c->quarter;
    case P_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            if (d == r) {
                continue;
            }
            if (c->acked[d] <= 3u * p + (uint32_t)ordinal_of(d, r)) {
                return false;
            }
        }
        return true;
    }
    return false;
}

static void extend_eligible(collector_t *c, int r) {
    if (c->mode == MODE_OWN) {
        c->E[r] = c->R[r];
        return;
    }
    while (c->E[r] < c->R[r] && contribution_safe(c, r, c->E[r])) {
        c->E[r]++;
    }
}

